from svg import box, t, arrow, svg

_C = [(300, 70, 'WHO', 'who, doing what'), (480, 70, 'CHANGE', 'feel, know, do'), (660, 70, 'FIXED', 'budget, time, tech'),
      (300, 180, 'PROOF', 'what counts as won'), (480, 180, 'DECIDER', 'who says yes'), (660, 180, 'RISK', 'what could break')]
_inner = box(20, 120, 240, 140, 's-card') + t(140, 178, 'THE REQUEST', 's-t-b') + t(140, 210, '"make it look premium"', 's-t-sm')
_inner += ''.join(box(x, y, 170, 95, 's-box-j') + t(x + 85, y + 40, a, 's-t-b') + t(x + 85, y + 68, b, 's-t-sm') for x, y, a, b in _C)
_inner += arrow(262, 190, 294, 190) + arrow(834, 190, 874, 190, True)
_inner += box(880, 110, 280, 160, 's-box-a') + t(1020, 152, 'THE FRAME', 's-t-b') + t(1020, 186, 'How might a first-time', 's-t-sm') + \
    t(1020, 212, 'safari guest compare lodges', 's-t-sm') + t(1020, 238, 'and keep the wonder?', 's-t-sm')
_inner += t(590, 340, 'A request names a look. A brief names a change, the limits and the proof.', 's-t-sm')
FIG = svg(1180, 370, 'From a request to a brief to a design question', _inner)

